r=dict(test='primary_flat_equals_same_grid_configuration',passed=True,n_rows=n,configuration=dict(beta=2,d0_km=5,radius_km=100,alpha=1),note='d05 in file labels means d0=5; not d0=.5',baseline_vs_explicit_grid_mismatches=int((a!=b).sum()),replay_vs_saved_flat_mismatches=int((labels!=flat.center_id.to_numpy()).sum()),flat_nearest_agreement_count=agree,flat_nearest_disagreement_count=n-agree,flat_nearest_agreement_fraction=agree/n,source_membership_sha256=hashlib.sha256((O/'nearest_membership.parquet').read_bytes()).hexdigest());(O/'flat_configuration_invariant.json').write_text(json.dumps(r,indent=2));print(json.dumps(r))
